command:
// Montée de niveau en un geste : une seule liste réunit les classes FQ déjà
// prises (montée d'un niveau) et celles encore disponibles dans les compendiums
// (ajout au niveau 1). La suite est laissée à l'assistant d'advancement dnd5e,
// qui reste seul maître de l'application des gains ; le moteur, lui, reconstruit
// le deck et ouvre le grimoire de son côté.
(async () => {
    // Plafond de niveau d'une classe FQ : au-delà, la progression passe
    // obligatoirement par une autre classe. Doit rester aligné sur
    // MAX_CLASS_LEVEL (src/domain/constants.js), qu'une macro ne peut pas lire ;
    // en dernier recours le hook preUpdateItem du moteur refuse la mise à jour.
    const MAX_CLASS_LEVEL = 12;
    const AdvancementManager = dnd5e.applications.advancement.AdvancementManager;
    const advancementsDisabled = game.settings.get("dnd5e", "disableAdvancements");
    const escape = (value) => foundry.utils.escapeHTML(String(value));

    // Le joueur agit sur son personnage ; le MJ peut viser un token sélectionné.
    const actor = game.user.character ?? canvas.tokens?.controlled?.[0]?.actor;
    if (!actor) return ui.notifications.warn("Aucun personnage : assignez-vous un personnage ou sélectionnez un token.");
    if (actor.type !== "character") return ui.notifications.warn("« " + actor.name + " » n'est pas un personnage joueur.");
    if (!actor.isOwner) return ui.notifications.warn("Vous n'êtes pas propriétaire de « " + actor.name + " ».");

    // Le moteur refuse tout advancement sur un acteur qu'aucun utilisateur n'a
    // pour personnage : sans propriétaire déclaré, le deck ne saurait à qui
    // appartenir. Autant le dire ici plutôt que de laisser l'assistant échouer.
    if (!game.users.some(user => user.character?.id === actor.id)) {
        return ui.notifications.warn("« " + actor.name + " » n'est le personnage d'aucun utilisateur : la montée de niveau est bloquée.");
    }

    if (actor.system.details.level >= CONFIG.DND5E.maxLevel) {
        return ui.notifications.warn("« " + actor.name + " » est déjà au niveau maximal (" + CONFIG.DND5E.maxLevel + ").");
    }

    const isFQSource = (source) => (source?.custom ?? source?.label) === "FQ";

    const ownedClasses = actor.itemTypes.class.filter(item => isFQSource(item.system.source));
    const ownedIdentifiers = new Set(ownedClasses.map(item => item.system.identifier));

    const levelUpEntries = ownedClasses
        .filter(item => item.system.levels < MAX_CLASS_LEVEL)
        .map(item => ({
            value: "level:" + item.id,
            label: item.name + " — niveau " + item.system.levels + " → " + (item.system.levels + 1),
            sort: item.name
        }))
        .sort((a, b) => a.sort.localeCompare(b.sort));

    const maxedClasses = ownedClasses.filter(item => item.system.levels >= MAX_CLASS_LEVEL);

    // Toute classe FQ, quel que soit le compendium qui la fournit : la liste suit
    // donc les compendiums réellement installés, sans id de pack en dur.
    const newEntries = [];
    const seenIdentifiers = new Set(ownedIdentifiers);
    for (const pack of game.packs.filter(pack => pack.documentName === "Item")) {
        const index = await pack.getIndex({fields: ["type", "system.identifier", "system.source"]});
        for (const entry of index) {
            if (entry.type !== "class" || !isFQSource(entry.system?.source)) continue;
            const identifier = entry.system?.identifier ?? entry.name;
            if (seenIdentifiers.has(identifier)) continue;
            seenIdentifiers.add(identifier);
            newEntries.push({
                value: "new:" + (entry.uuid ?? ("Compendium." + pack.metadata.id + ".Item." + entry._id)),
                label: entry.name + " — nouvelle classe, niveau 1",
                sort: entry.name
            });
        }
    }
    newEntries.sort((a, b) => a.sort.localeCompare(b.sort));

    if (!levelUpEntries.length && !newEntries.length) {
        return ui.notifications.warn("Aucune classe FQ à monter ni à ajouter pour « " + actor.name + " ».");
    }

    const optionGroup = (label, entries) => entries.length
        ? "<optgroup label=\"" + escape(label) + "\">"
            + entries.map(entry => "<option value=\"" + escape(entry.value) + "\">" + escape(entry.label) + "</option>").join("")
            + "</optgroup>"
        : "";

    const content = [
        "<p><strong>" + escape(actor.name) + "</strong> — niveau " + actor.system.details.level + "</p>",
        maxedClasses.length
            ? "<p class=\"notes\">Au plafond (" + MAX_CLASS_LEVEL + ") : "
                + escape(maxedClasses.map(item => item.name).join(", ")) + ".</p>"
            : "",
        "<div class=\"form-group\"><label>Progression</label>",
        "<select name=\"choice\" style=\"max-width: 22rem;\">",
        optionGroup("Monter d'un niveau", levelUpEntries),
        optionGroup("Ajouter une classe", newEntries),
        "</select></div>"
    ].join("");

    const choice = await foundry.applications.api.DialogV2.prompt({
        window: {title: "Montée de niveau"},
        content,
        ok: {
            label: "Valider",
            callback: (event, button) => button.form.elements.choice.value
        },
        rejectClose: false
    });
    if (!choice) return;

    // Montée d'une classe déjà présente : même chemin que le sélecteur de niveau
    // de la fiche dnd5e — l'assistant s'il a des étapes, la mise à jour directe sinon.
    if (choice.startsWith("level:")) {
        const classItem = actor.items.get(choice.slice("level:".length));
        if (!classItem) return ui.notifications.error("Classe introuvable sur « " + actor.name + " ».");
        // Le plafond est revérifié au moment d'appliquer : la liste a pu être
        // construite avant une montée venue d'ailleurs (autre client, MJ).
        if (classItem.system.levels >= MAX_CLASS_LEVEL) {
            return ui.notifications.warn(game.i18n.format("FQCARDENGINE.MaxClassLevelReached", {max: MAX_CLASS_LEVEL}));
        }
        if (!advancementsDisabled) {
            const manager = AdvancementManager.forLevelChange(actor, classItem.id, 1);
            if (manager.steps.length) return manager.render(true);
        }
        await classItem.update({"system.levels": classItem.system.levels + 1});
        return ui.notifications.info(classItem.name + " : niveau " + classItem.system.levels + ".");
    }

    const source = await fromUuid(choice.slice("new:".length));
    if (!source) return ui.notifications.error("Classe introuvable dans les compendiums.");

    // `fromCompendium` nettoie l'id et la propriété comme le fait un glisser-déposer
    // sur la fiche ; le niveau 1 est imposé quoi qu'annonce le compendium.
    const itemData = game.items.fromCompendium(source);
    itemData.system.levels = 1;

    if (!advancementsDisabled && !foundry.utils.isEmpty(itemData.system.advancement)) {
        const manager = AdvancementManager.forNewItem(actor, itemData);
        if (manager.steps.length) return manager.render(true);
    }
    await actor.createEmbeddedDocuments("Item", [itemData]);
    ui.notifications.info(itemData.name + " ajouté à « " + actor.name + " » au niveau 1.");
})();
